// ============================================================================
// WF-26 · צירוף לקבוצת וואטסאפ — הכנת הקריאה
// ============================================================================
// זהו ה-workflow היחיד שמחזיק את מפתח GreenAPI. שאר התהליכים קוראים לו
// דרך וובהוק פנימי, וכך ה-JSON שלהם ניתן לייצוא בלי לחשוף שום מפתח.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const cfg = ctx.cfg;
  const raw = ctx.raw || {};
  const d = (raw && raw.body && typeof raw.body === 'object') ? raw.body : raw;
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const inst = `${cfg.API_BASE}/waInstance${cfg.ID_INSTANCE}`;
  return [{ json: {
    groupId: S(d.groupId), chatId: S(d.chatId), groupName: S(d.groupName),
    groupRecordId: S(d.groupRecordId), accountName: S(d.accountName),
    source: S(d.source), executionUrl: S(d.executionUrl),
    stateUrl: `${inst}/getStateInstance/${cfg.API_TOKEN}`,
    joinUrlTemplate: `${inst}/addGroupParticipant/${cfg.API_TOKEN}`,
    idleUrl: `${inst}/getStateInstance/${cfg.API_TOKEN}`,
  } }];
}

// ==== N8N BINDING ====
return LOGIC({ raw: $('Webhook · צירוף לקבוצה').first().json, cfg: $('קונפיגורציה').first().json });

// ============================================================================
// WF-26 · הכרעה — האם החיבור מורשה ואפשר לצרף
// ============================================================================
// 🔴 כלל מהפלייבוק: קריאה ראשונה חובה ל-getStateInstance, והוא חייב להחזיר
//    authorized. כל מצב אחר ⇒ לא מנסים לצרף, מחזירים סיבה, והלקוחה תצטרף
//    דרך קישור ההזמנה שנשלח בהודעת הוולקאם.
// ============================================================================

// ==== LOGIC (pure) ====
function LOGIC(ctx) {
  const prep = ctx.prep;
  const state = String((ctx.stateResp && (ctx.stateResp.stateInstance
    || (ctx.stateResp.data && ctx.stateResp.data.stateInstance))) || '').trim();
  const authorized = state === 'authorized';

  const STATE_TEXT = {
    notAuthorized: 'המכשיר לא מחובר — נדרשת סריקת QR מחדש',
    authorized: 'מחובר',
    blocked: 'החשבון חסום ב-GreenAPI',
    sleepMode: 'המכשיר במצב שינה',
    starting: 'המופע בהפעלה',
    expired: '🔴 המנוי/החיבור פג תוקף — נדרשת סריקת QR מחדש',
  };

  if (!prep.groupId || !prep.chatId) {
    return [{ json: Object.assign({}, prep, { skip: true, joined: false, state,
      reason: 'חסר מזהה קבוצה או טלפון', callUrl: prep.idleUrl, callBody: {} }) }];
  }
  if (!authorized) {
    return [{ json: Object.assign({}, prep, { skip: true, joined: false, state,
      reason: STATE_TEXT[state] || `מצב חיבור לא תקין (${state || 'לא ידוע'})`,
      callUrl: prep.idleUrl, callBody: {} }) }];
  }
  return [{ json: Object.assign({}, prep, { skip: false, state, reason: '',
    callUrl: prep.joinUrlTemplate,
    callBody: { groupId: prep.groupId, participantChatId: prep.chatId } }) }];
}

// ==== N8N BINDING ====
return LOGIC({ prep: $('הכנת הקריאה').first().json, stateResp: $input.first().json });

// ============================================================================
// WF-26 · סיכום תוצאת הצירוף
// ============================================================================

// ==== LOGIC (pure) ====
// 🔴 כל מצב חיבור שאינו authorized מפעיל מיד את WF-21, שבודק את התקינות
//    ושולח מייל לרויטל אם צריך. בלי זה התקלה מתגלה רק ב-08:00 או ב-20:00.
//    WF-21 מחזיק בעצמו מנגנון מניעת הצפה — מייל אחד לאירוע.
const ALERT_URL = 'https://n8n.srv964196.hstgr.cloud/webhook/greenapi-check-now';

function alertOn(state, extra) {
  const bad = String(state || '').trim() !== 'authorized';
  if (!bad) return { _alertUrl: 'https://n8n.srv964196.hstgr.cloud/healthz', _alertMethod: 'GET', _alertBody: {}, _alertFired: false };
  return {
    _alertUrl: ALERT_URL, _alertMethod: 'POST', _alertFired: true,
    _alertBody: { source: 'WF-26 · צירוף לקבוצת וואטסאפ',
      detail: 'מצב החיבור: ' + (state || 'לא ידוע') + (extra ? ' · ' + extra : '') },
  };
}

function LOGIC(ctx) {
  const dec = ctx.decision;
  const r = ctx.resp || {};
  if (dec.skip) {
    return [{ json: Object.assign({ joined: false, skipped: true, reason: dec.reason, state: dec.state,
      groupName: dec.groupName, chatId: dec.chatId }, alertOn(dec.state, dec.groupName)) }];
  }
  const added = r.addParticipant === true || (r.data && r.data.addParticipant === true);
  const errText = String((r && (r.error || (r.message && !r.addParticipant && r.message))) || '');
  return [{ json: Object.assign({
    joined: !!added, skipped: false, state: dec.state,
    reason: added ? ''
      : (errText ? ('הקריאה ל-GreenAPI נכשלה: ' + errText)
                 : 'GreenAPI לא אישר את הצירוף — ייתכן שהגדרות הפרטיות של הלקוחה חוסמות'),
    groupName: dec.groupName, chatId: dec.chatId, response: r,
  }, alertOn(dec.state, errText)) }];
}

// ==== N8N BINDING ====
return LOGIC({ decision: $('הכרעת צירוף').first().json, resp: $input.first().json });
